-- Alpha execution layer v4: outcome-free precondition evidence, append-only
-- attempt lifecycle, conservative label-access metadata, resource accounting,
-- and durable result pointers.  Statistical result bytes never enter SQLite.
CREATE TABLE precondition_evidence (
 evidence_sha256 TEXT PRIMARY KEY CHECK(length(evidence_sha256)=64),
 proposal_id TEXT NOT NULL UNIQUE REFERENCES authority_proposals(proposal_id),
 evidence_json TEXT NOT NULL CHECK(json_valid(evidence_json)),
 preconditions_transition_id INTEGER NOT NULL UNIQUE REFERENCES authority_transitions(transition_id),
 daemon_recorded_at TEXT NOT NULL
) STRICT;

CREATE TABLE trial_attempt_events (
 attempt_event_id TEXT PRIMARY KEY,
 attempt_id TEXT NOT NULL REFERENCES trial_attempts(attempt_id),
 event_ordinal INTEGER NOT NULL CHECK(event_ordinal IN (1,2)),
 state TEXT NOT NULL CHECK(state IN ('RUNNING','ATTEMPT_VOID','COMPLETED')),
 boot_id TEXT NOT NULL,
 daemon_pid INTEGER NOT NULL CHECK(daemon_pid>0),
 monotonic_ns INTEGER NOT NULL CHECK(monotonic_ns>=0),
 active_elapsed_ns INTEGER CHECK(active_elapsed_ns IS NULL OR active_elapsed_ns>=0),
 checkpoint_sha256 TEXT CHECK(checkpoint_sha256 IS NULL OR length(checkpoint_sha256)=64),
 daemon_recorded_at TEXT NOT NULL,
 UNIQUE(attempt_id,event_ordinal)
) STRICT;

CREATE TABLE label_access_ledger (
 label_access_id TEXT PRIMARY KEY,
 proposal_id TEXT NOT NULL REFERENCES authority_proposals(proposal_id),
 logical_trial_id TEXT NOT NULL REFERENCES logical_trials(logical_trial_id),
 attempt_id TEXT NOT NULL REFERENCES trial_attempts(attempt_id),
 access_kind TEXT NOT NULL CHECK(access_kind IN ('T1','W1')),
 binding_sha256 TEXT NOT NULL CHECK(length(binding_sha256)=64),
 evaluator_sha256 TEXT NOT NULL CHECK(length(evaluator_sha256)=64),
 frozen_weight_set_sha256 TEXT NOT NULL CHECK(length(frozen_weight_set_sha256)=64),
 t1_seal_sha256 TEXT CHECK(t1_seal_sha256 IS NULL OR length(t1_seal_sha256)=64),
 daemon_recorded_at TEXT NOT NULL,
 UNIQUE(logical_trial_id,access_kind)
) STRICT;

CREATE TABLE wave_resource_events (
 resource_event_id TEXT PRIMARY KEY,
 proposal_id TEXT NOT NULL REFERENCES authority_proposals(proposal_id),
 logical_trial_id TEXT NOT NULL REFERENCES logical_trials(logical_trial_id),
 attempt_id TEXT NOT NULL REFERENCES trial_attempts(attempt_id),
 event_kind TEXT NOT NULL CHECK(event_kind IN ('ATTEMPT_STARTED','ATTEMPT_CLOSED','CHECKPOINT_SEALED')),
 policy_sha256 TEXT NOT NULL CHECK(length(policy_sha256)=64),
 cumulative_active_ns INTEGER NOT NULL CHECK(cumulative_active_ns>=0),
 daemon_recorded_at TEXT NOT NULL,
 UNIQUE(attempt_id,event_kind)
) STRICT;

CREATE TABLE sealed_results (
 result_sha256 TEXT PRIMARY KEY CHECK(length(result_sha256)=64),
 result_kind TEXT NOT NULL CHECK(result_kind IN ('T1','W1')),
 proposal_id TEXT NOT NULL UNIQUE REFERENCES authority_proposals(proposal_id),
 logical_trial_id TEXT NOT NULL UNIQUE REFERENCES logical_trials(logical_trial_id),
 attempt_id TEXT NOT NULL UNIQUE REFERENCES trial_attempts(attempt_id),
 artifact_relpath TEXT NOT NULL UNIQUE,
 artifact_size INTEGER NOT NULL CHECK(artifact_size>0),
 result_state TEXT CHECK(result_state IS NULL OR result_state IN ('REPLICATION_SUPPORTED','REPLICATION_FAILED','EVIDENCE_INSUFFICIENT_CURRENT_COHORT','TEST_VOIDED')),
 binding_sha256 TEXT NOT NULL CHECK(length(binding_sha256)=64),
 evaluator_sha256 TEXT NOT NULL CHECK(length(evaluator_sha256)=64),
 daemon_recorded_at TEXT NOT NULL
) STRICT;

CREATE TRIGGER precondition_binding_guard BEFORE INSERT ON precondition_evidence BEGIN SELECT CASE
 WHEN (SELECT proposal_id FROM authority_transitions WHERE transition_id=NEW.preconditions_transition_id)!=NEW.proposal_id THEN RAISE(ABORT,'precondition evidence proposal mismatch')
 WHEN (SELECT to_state FROM authority_transitions WHERE transition_id=NEW.preconditions_transition_id)!='PRECONDITIONS_PASS' THEN RAISE(ABORT,'precondition evidence requires PRECONDITIONS_PASS') END; END;

CREATE TRIGGER trial_attempt_event_order BEFORE INSERT ON trial_attempt_events BEGIN SELECT CASE
 WHEN NEW.event_ordinal=1 AND (NEW.state!='RUNNING' OR EXISTS(SELECT 1 FROM trial_attempt_events WHERE attempt_id=NEW.attempt_id)) THEN RAISE(ABORT,'attempt must start RUNNING exactly once')
 WHEN NEW.event_ordinal=2 AND (NEW.state='RUNNING' OR NOT EXISTS(SELECT 1 FROM trial_attempt_events WHERE attempt_id=NEW.attempt_id AND event_ordinal=1 AND state='RUNNING') OR EXISTS(SELECT 1 FROM trial_attempt_events WHERE attempt_id=NEW.attempt_id AND event_ordinal=2)) THEN RAISE(ABORT,'attempt terminal event invalid')
 WHEN NEW.event_ordinal=1 AND EXISTS(
   SELECT 1 FROM trial_attempt_events e JOIN trial_attempts olda ON olda.attempt_id=e.attempt_id
   JOIN trial_attempts newa ON newa.attempt_id=NEW.attempt_id
   WHERE olda.logical_trial_id=newa.logical_trial_id AND e.state='RUNNING'
   AND NOT EXISTS(SELECT 1 FROM trial_attempt_events t WHERE t.attempt_id=e.attempt_id AND t.event_ordinal=2)
 ) THEN RAISE(ABORT,'logical trial already has a RUNNING attempt') END; END;

CREATE TRIGGER w1_label_requires_t1_seal BEFORE INSERT ON label_access_ledger WHEN NEW.access_kind='W1' BEGIN SELECT CASE
 WHEN NEW.t1_seal_sha256 IS NULL THEN RAISE(ABORT,'W1 label access requires T1 seal')
 WHEN NOT EXISTS(SELECT 1 FROM sealed_results WHERE result_sha256=NEW.t1_seal_sha256 AND result_kind='T1' AND result_state!='TEST_VOIDED') THEN RAISE(ABORT,'W1 label access requires non-void T1 seal') END; END;

CREATE TRIGGER sealed_result_requires_completed_attempt BEFORE INSERT ON sealed_results BEGIN SELECT CASE
 WHEN NOT EXISTS(SELECT 1 FROM trial_attempt_events WHERE attempt_id=NEW.attempt_id AND event_ordinal=2 AND state='COMPLETED') THEN RAISE(ABORT,'sealed result requires completed attempt')
 WHEN NEW.result_kind='T1' AND NEW.result_state IS NULL THEN RAISE(ABORT,'T1 sealed result state required')
 WHEN NEW.result_kind='W1' AND NEW.result_state IS NOT NULL THEN RAISE(ABORT,'W1 sealed result must not expose T1 state') END; END;

CREATE TRIGGER precondition_evidence_no_update BEFORE UPDATE ON precondition_evidence BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER precondition_evidence_no_delete BEFORE DELETE ON precondition_evidence BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER trial_attempt_events_no_update BEFORE UPDATE ON trial_attempt_events BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER trial_attempt_events_no_delete BEFORE DELETE ON trial_attempt_events BEGIN SELECT RAISE(ABORT,'append-only'); END;
